        nSavedSearchIdx = nSearchTileIdx;
        nTileWalkFlags = D2CMP::DUNGEON::Dungeon::TILEPROJECT_GetTileCount((int32_t)pFloorTiles[nSearchTileIdx].pTileLibraryEntry);
